    if(legacy&&creation){ev.preventDefault();ev.stopImmediatePropagation();const c=C.ctx();if(legacy.dataset.cm==='asset-category')library(c,legacy.dataset.type);else if(legacy.dataset.cm==='shot-edit')toolPanel(c);else toolPanel(c,'panel');return;}
    const assetLink=ev.target.closest('a[href="#/app/assets"],a[href="#/app/tools"]');if(assetLink&&creation){ev.preventDefault();ev.stopImmediatePropagation();if(assetLink.hash.endsWith('/assets'))library(C.ctx());else toolPanel(C.ctx());return;}
    const el=ev.target.closest('[data-prod]');if(!el)return;ev.preventDefault();ev.stopImmediatePropagation();const c=C.ctx(),e=c.e,s=active(c),action=el.dataset.prod;
